        </div>
    @endforeach
    <!-- MODALS (moved from insights.blade.php) -->
    <div x-show="textOpen" x-on:keydown.escape.window="textOpen = false" class="lp-fixed lp-inset-0 lp-flex lp-items-center lp-justify-center lp-bg-black/50 lp-z-50">
        <div class="lp-bg-surface lp-rounded lp-p-6 lp-w-full lp-max-w-2xl lp-space-y-4">
            <div class="lp-flex lp-items-start lp-space-x-3">
