    <div x-show="videoOpen" x-on:keydown.escape.window="videoOpen = false" class="lp-fixed lp-inset-0 lp-flex lp-items-center lp-justify-center lp-bg-black/50 lp-z-50">
        <div class="lp-bg-surface lp-rounded lp-p-6 lp-w-full lp-max-w-3xl lp-h-full lp-overflow-auto">
            <div class="lp-space-y-3">
