| `resources/js/workflow-alpine.js` (renamed from `insights-alpine.js`) | Factory `workflow(groups)` with specified state & methods. | ```javascript
export default function workflow(groups) {
    return {
        groups: groups || [],
        tips: [],
        rotateIdx: 0,
        playing: false,
        audio: null,
        selected: null,
        textOpen: false,
        videoOpen: false,
        paused: false,
        rotateInterval: null,
        init() {
            this.flattenTips();
            this.startRotate();
            document.addEventListener('lp-audio-play', e => {
                if (e.detail.source !== 'workflow' && this.playing) this.stopAudio();
            });
        },
        destroy() { clearInterval(this.rotateInterval); },
        flattenTips() {
            this.tips = this.groups.flatMap(g => g.tips.map(t => ({
                tip: t,
                accent: g.accent,
                title: g.title,
                key: g.key,
                route: g.route
            })));
        },
        startRotate() {
            this.rotateInterval = setInterval(() => {
                if (!this.tips.length || this.textOpen || this.videoOpen || this.playing || this.paused) return;
                this.rotateIdx = (this.rotateIdx + 1) % this.tips.length;
            }, 7000);
        },
        nextTip() { this.rotateIdx = (this.rotateIdx + 1) % this.tips.length; },
        togglePause() { this.paused = !this.paused; },
        openText(group) {
            const g = this.groups.find(g => g.key === group);
            this.selected = group;
            this.selectedGroupTitle = g.title;
            this.selectedGroupContent = this.buildTextContent(g);
            this.textOpen = true;
        },
        openVideo(group) {
            const g = this.groups.find(g => g.key === group);
            this.selected = group;
            this.selectedGroupTitle = g.title;
            this.selectedGroupVideo = g.video;
            this.videoOpen = true;
        },
        playPause(group) {
            if (this.playing && this.selected === group) { this.stopAudio(); return; }
            const g = this.groups.find(g => g.key === group);
            this.stopAudio();
            this.audio = new Audio(g.audio);
            this.audio.play();
            this.playing = true;
            this.selected = group;
            this.dispatchAudioEvent();
        },
        stopAudio() {
            if (this.audio) { this.audio.pause(); this.audio = null; }
            this.playing = false;
        },
        dispatchAudioEvent() {
            document.dispatchEvent(new CustomEvent('lp-audio-play', {detail: {source: 'workflow'}}));
        },
        // getters for template
